using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalTests
{
    private readonly CalculatePayableTotal _calculatePayableTotal = CreateCalculatePayableTotal();

    [Fact]
    public void WhenGoldMemberSubtotalIs100_ShouldPay95()
    {
        var payableTotalCents = _calculatePayableTotal.For(10_000, LoyaltyTier.Gold);

        Assert.Equal(9_500, payableTotalCents);
    }

    [Fact]
    public void WhenGoldMemberSubtotalIs200_ShouldPay190()
    {
        var payableTotalCents = _calculatePayableTotal.For(20_000, LoyaltyTier.Gold);

        Assert.Equal(19_000, payableTotalCents);
    }

    [Fact]
    public void WhenGoldMemberSubtotalIs50_ShouldPay47_50()
    {
        var payableTotalCents = _calculatePayableTotal.For(5_000, LoyaltyTier.Gold);

        Assert.Equal(4_750, payableTotalCents);
    }

    [Fact]
    public void WhenGoldMemberCartIsEmpty_ShouldPayNothing()
    {
        var payableTotalCents = _calculatePayableTotal.For(0, LoyaltyTier.Gold);

        Assert.Equal(0, payableTotalCents);
    }

    private static CalculatePayableTotal CreateCalculatePayableTotal() =>
        new(new LoyaltyDiscountPolicy());
}
